    /* accent */
  --hui-showcase-accent: var(--blue);
    /* bg */
  --hui-showcase-bg: var(--surface-alt);
    /* border */
  --hui-showcase-border: var(--border);
    /* cell */
  --hui-showcase-cell-bg: var(--surface);
  --hui-showcase-cell-border: var(--border);
    /* label */
  --hui-showcase-label-color: var(--text-muted);

  /* Seeds */
  --white: #FAF7F2;
  --black: #2C1810;
  --red: #C05621;
  --blue: #2D5F2D;
  --yellow: #D4A017;
  --font-sans: 'Lora', 'Georgia', 'Palatino Linotype', serif;
  --font-mono: 'JetBrains Mono', 'Cascadia Code', 'Fira Code', monospace;
  --radius: 16px;
  --unit: 10px;

  /* Neutrals */
    /* 50 */
  --gray-50: #FAF7F2;
    /* 100 */
  --gray-100: #F5F0E8;
    /* 200 */
  --gray-200: #E8E0D4;
    /* 300 */
  --gray-300: #D4C9BA;
    /* 400 */
  --gray-400: #A89A8A;
    /* 500 */
  --gray-500: #7D7068;
    /* 600 */
  --gray-600: #5C5048;
    /* 700 */
  --gray-700: #3E3530;
    /* 800 */
  --gray-800: #2C2420;
    /* 900 */
  --gray-900: #2C1810;

  /* Accent Primaries */
  --red-light: rgba(192,86,33,0.08);
  --red-mid: rgba(192,86,33,0.15);
  --blue-light: rgba(45,95,45,0.08);
  --blue-mid: rgba(45,95,45,0.15);
  --yellow-light: rgba(212,160,23,0.10);
  --yellow-mid: rgba(212,160,23,0.20);

  /* Extended Palette */
  --violet: #7B4F3A;
  --violet-light: rgba(123,79,58,0.08);
  --violet-mid: rgba(123,79,58,0.15);
  --emerald: #2D5F2D;
  --emerald-light: rgba(45,95,45,0.08);
  --cyan: #4A7B6F;
  --cyan-light: rgba(74,123,111,0.08);
  --rose: #B85450;
  --rose-light: rgba(184,84,80,0.08);
  --amber: #D4A017;
  --amber-light: rgba(212,160,23,0.08);
  --indigo: #5B6B4F;
  --indigo-light: rgba(91,107,79,0.08);
  --teal: #4A7B6F;
  --teal-light: rgba(74,123,111,0.08);
  --orange: #C05621;
  --orange-light: rgba(192,86,33,0.08);
  --sky: #6B8E7B;
  --sky-light: rgba(107,142,123,0.08);
  --lime: #6B8B3D;
  --lime-light: rgba(107,139,61,0.08);
  --pink: #B87070;
  --pink-light: rgba(184,112,112,0.08);
  --fuchsia: #9B6B8A;
  --fuchsia-light: rgba(155,107,138,0.08);
  --purple: #7B5F7B;
  --purple-light: rgba(123,95,123,0.08);
  --sage: #8B9E7C;
  --sage-light: rgba(139,158,124,0.08);

  /* Spacing */
  --space-quarter: 2.5px;
  --space-half: 5px;
  --space-1: 10px;
  --space-2: 20px;
  --space-3: 30px;
  --space-4: 40px;
  --space-5: 50px;
  --space-6: 60px;
  --space-8: 80px;
  --space-10: 100px;
  --space-12: 120px;
  --col-gap: 16px;

  /* Radius */
  --radius-sm: 8px;
  --radius-md: 16px;
  --radius-lg: 20px;

  /* Section Chrome */
  --sg-section-title-font-family: var(--font-display);
  --sg-section-title-text-transform: none;
  --sg-section-title-letter-spacing: -0.01em;
  --sg-section-title-color: var(--text);
  --sg-section-number-bg: var(--blue);
  --sg-section-number-border: none;
  --sg-section-number-color: #FAF7F2;
  --sg-section-number-radius: var(--radius-sm);
  --sg-section-desc-font-family: var(--font-sans);
  --sg-section-desc-color: var(--text-muted);
  --sg-type-specimen-bg: var(--surface-alt);
  --sg-type-specimen-border: 1px solid var(--border);
  --sg-type-specimen-border-bottom: 2px solid var(--blue);
  --sg-type-specimen-radius: var(--radius-md);
  --sg-type-specimen-padding: var(--space-3);
  --sg-type-specimen-margin: 0 0 var(--space-2) 0;
  --sg-type-specimen-name-color: var(--text);
  --sg-type-specimen-name-font: var(--font-display);
  --hr-section-height: 1px;
  --hr-section-color: var(--border);
  --hr-subsection-color: var(--border);
  --hr-subsection-height: 1px;
  --hr-accent-color: var(--blue);
}

/* ── SCOPED-VARS ── */
html[data-design-theme="organic"] {
  --theme-surface: var(--white);
  --theme-surface-alt: var(--gray-50);
  --theme-surface-inverse: var(--gray-900);
  --theme-text: var(--gray-900);
  --theme-text-secondary: var(--gray-600);
