  --theme-text-inverse: var(--white);
  --theme-text-link: #2D5F2D;
  --theme-border: var(--gray-200);
  --theme-border-strong: var(--gray-300);
  --theme-shadow-color: rgba(44,24,16,0.06);
  --layout-dashboard-max-width: 1440px;
  --layout-dashboard-padding: var(--space-3);
  --layout-dashboard-margin: 0 auto;
  --layout-dashboard-content-bg: var(--surface);
