  --theme-blue-light: color-mix(in srgb, #2D5F2D 18%, var(--surface));
  --theme-blue-mid: color-mix(in srgb, #2D5F2D 30%, var(--surface));
  --theme-violet: color-mix(in srgb, #7B4F3A 75%, white);
  --theme-violet-light: color-mix(in srgb, #7B4F3A 18%, var(--surface));
  --theme-violet-mid: color-mix(in srgb, #7B4F3A 30%, var(--surface));
  --theme-rose: color-mix(in srgb, #B85450 75%, white);
  --theme-rose-light: color-mix(in srgb, #B85450 18%, var(--surface));
  --theme-emerald: color-mix(in srgb, #2D5F2D 75%, white);
  --theme-emerald-light: color-mix(in srgb, #2D5F2D 18%, var(--surface));
  --theme-amber: color-mix(in srgb, #D4A017 75%, white);
  --theme-amber-light: color-mix(in srgb, #D4A017 18%, var(--surface));
  --theme-cyan: color-mix(in srgb, #4A7B6F 75%, white);
  --theme-cyan-light: color-mix(in srgb, #4A7B6F 18%, var(--surface));
  --theme-indigo: color-mix(in srgb, #5B6B4F 75%, white);
  --theme-indigo-light: color-mix(in srgb, #5B6B4F 18%, var(--surface));
  --theme-teal: color-mix(in srgb, #4A7B6F 75%, white);
  --theme-teal-light: color-mix(in srgb, #4A7B6F 18%, var(--surface));
  --theme-orange: color-mix(in srgb, #C05621 75%, white);
  --theme-orange-light: color-mix(in srgb, #C05621 18%, var(--surface));
  --theme-sky: color-mix(in srgb, #6B8E7B 75%, white);
  --theme-sky-light: color-mix(in srgb, #6B8E7B 18%, var(--surface));
  --theme-lime: color-mix(in srgb, #6B8B3D 75%, white);
  --theme-lime-light: color-mix(in srgb, #6B8B3D 18%, var(--surface));
  --theme-pink: color-mix(in srgb, #B87070 75%, white);
  --theme-pink-light: color-mix(in srgb, #B87070 18%, var(--surface));
  --theme-purple: color-mix(in srgb, #7B5F7B 75%, white);
  --theme-purple-light: color-mix(in srgb, #7B5F7B 18%, var(--surface));
  --theme-fuchsia: color-mix(in srgb, #9B6B8A 75%, white);
  --theme-fuchsia-light: color-mix(in srgb, #9B6B8A 18%, var(--surface));
  --theme-success: color-mix(in srgb, #2D5F2D 75%, white);
  --theme-success-tint: color-mix(in srgb, #2D5F2D 18%, var(--surface));
  --theme-warning: color-mix(in srgb, #D4A017 75%, white);
  --theme-warning-tint: color-mix(in srgb, #D4A017 18%, var(--surface));
  --theme-error: color-mix(in srgb, #C05621 75%, white);
  --theme-error-tint: color-mix(in srgb, #C05621 18%, var(--surface));
  --theme-info: color-mix(in srgb, #5B7F5B 75%, white);
  --theme-info-tint: color-mix(in srgb, #5B7F5B 18%, var(--surface));
  --theme-card-background: var(--gray-800);
  --theme-card-border-color: var(--gray-700);
  --theme-btn-background: #245024;
  --theme-btn-hover-background: #2D5F2D;
}

/* Alias layer: bare names → themed vars */
html[data-design-theme="organic"] {
  --surface: var(--theme-surface);
