  border-color: color-mix(in srgb, var(--semantic-state-down-accent) 85%, black);
}
html[data-design-theme="organic"] .btn.state-down.drop-shadow {
  box-shadow: 0 8px 24px color-mix(in srgb, var(--semantic-state-down-accent) 35%, transparent), 0 2px 6px color-mix(in srgb, var(--semantic-state-down-accent) 20%, transparent);
}

/* Button ghost: .btn.btn-ghost.state-down */
html[data-design-theme="organic"] .btn.btn-ghost.state-down {
  background: transparent;
  border-color: transparent;
  color: var(--semantic-state-down-accent);
}
html[data-design-theme="organic"] .btn.btn-ghost.state-down:hover {
  background: color-mix(in srgb, var(--semantic-state-down-accent) 10%, transparent);
}

/* Button outline: .btn.btn-outline.state-down */
html[data-design-theme="organic"] .btn.btn-outline.state-down {
  background: transparent;
  border-color: var(--semantic-state-down-accent);
  color: var(--semantic-state-down-accent);
}
html[data-design-theme="organic"] .btn.btn-outline.state-down:hover {
  background: color-mix(in srgb, var(--semantic-state-down-accent) 10%, transparent);
}

/* Button accent: .btn.accent-state-down — bottom border + inset bottom shadow only */
html[data-design-theme="organic"] .btn.accent-state-down {
  border-bottom-color: var(--semantic-state-down-accent);
  border-bottom-width: 2px;
  box-shadow: inset 0 -3px 6px color-mix(in srgb, var(--semantic-state-down-accent) 25%, transparent);
}
html[data-design-theme="organic"] .btn.accent-state-down.drop-shadow {
  box-shadow: inset 0 -3px 6px color-mix(in srgb, var(--semantic-state-down-accent) 25%, transparent), 0 8px 24px color-mix(in srgb, var(--semantic-state-down-accent) 35%, transparent);
}

/* Button outline accent: .btn.btn-outline.accent-state-down */
html[data-design-theme="organic"] .btn.btn-outline.accent-state-down {
  border-color: var(--semantic-state-down-accent);
  color: var(--semantic-state-down-accent);
}
html[data-design-theme="organic"] .btn.btn-outline.accent-state-down:hover {
  background: color-mix(in srgb, var(--semantic-state-down-accent) 10%, transparent);
}

/* Selected state: fade in animated gradient overlay via ::before */
html[data-design-theme="organic"] .btn.state-down.btn-selected {
  border-color: color-mix(in srgb, var(--semantic-state-down-accent) 70%, black);
  box-shadow: inset 0 2px 6px color-mix(in srgb, var(--semantic-state-down-accent) 40%, black), inset 0 1px 2px rgba(0,0,0,0.3);
}
html[data-design-theme="organic"] .btn.state-down.btn-selected::before {
  opacity: 1;
  animation: btn-selected-gradient 2.5s ease infinite;
}

/* HUI: Trigger buttons */
.hui.menu-btn.state-down,
html[data-design-theme="organic"] .hui.popover-btn.state-down {
  border-color: var(--semantic-state-down-accent);
  color: var(--semantic-state-down-color);
}
.hui.menu-btn.state-down[data-hover],
html[data-design-theme="organic"] .hui.popover-btn.state-down[data-hover] {
  background: var(--semantic-state-down-background);
}

/* HUI: Overlay panels */
.hui.menu-items.state-down,
.hui.listbox-options.state-down,
.hui.combo-options.state-down,
html[data-design-theme="organic"] .hui.popover-panel.state-down {
  border-left: var(--hui-showcase-accent-width) solid var(--semantic-state-down-accent);
  border-color: color-mix(in srgb, var(--semantic-state-down-accent) 40%, var(--hui-panel-border));
  background: var(--semantic-state-down-background);
}

/* HUI: Listbox & Combobox field-style triggers */
html[data-design-theme="organic"] .hui.listbox-btn.state-down {
  border-color: color-mix(in srgb, var(--semantic-state-down-accent) 40%, var(--hui-field-border));
}
html[data-design-theme="organic"] .hui.listbox-btn.state-down[data-open] {
  border-color: var(--semantic-state-down-accent);
  box-shadow: 0 0 0 var(--hui-focus-ring-width) color-mix(in srgb, var(--semantic-state-down-accent) 25%, transparent), var(--hui-field-shadow);
}
html[data-design-theme="organic"] .hui.listbox-btn.state-down::after {
  border-right-color: var(--semantic-state-down-accent);
  border-bottom-color: var(--semantic-state-down-accent);
}
html[data-design-theme="organic"] .hui.combo-input.state-down {
  border-color: color-mix(in srgb, var(--semantic-state-down-accent) 40%, var(--hui-field-border));
}
html[data-design-theme="organic"] .hui.combo-input.state-down:focus {
  border-color: var(--semantic-state-down-accent);
  box-shadow: 0 0 0 var(--hui-focus-ring-width) color-mix(in srgb, var(--semantic-state-down-accent) 25%, transparent), var(--hui-field-shadow);
}
html[data-design-theme="organic"] .hui.combo-btn.state-down {
  color: var(--semantic-state-down-accent);
}

/* HUI: Dialog */
html[data-design-theme="organic"] .hui.dialog-panel.state-down {
  border-left: var(--hui-showcase-accent-width) solid var(--semantic-state-down-accent);
}
html[data-design-theme="organic"] .hui.dialog-panel.state-down .dialog-title {
  color: var(--semantic-state-down-accent);
}

/* HUI: Tabs */
html[data-design-theme="organic"] .hui.tab-list.state-down .hui.tab[data-selected] {
  color: var(--semantic-state-down-accent);
  border-bottom-color: var(--semantic-state-down-accent);
}

/* HUI: Disclosure */
html[data-design-theme="organic"] .hui.disclosure-btn.state-down {
  border-color: var(--semantic-state-down-accent);
  background: var(--semantic-state-down-background);
}

/* HUI: Controls — on state */
html[data-design-theme="organic"] .hui.checkbox-wrap.state-down[data-checked] .checkbox-visual {
  background: var(--semantic-state-down-accent);
  border-color: var(--semantic-state-down-accent);
}
html[data-design-theme="organic"] .hui.switch-wrap.state-down[data-checked] .switch-track {
  background: var(--semantic-state-down-accent);
}
html[data-design-theme="organic"] .hui.radio-option.state-down[data-checked] {
  border-color: var(--semantic-state-down-accent);
  background: var(--semantic-state-down-background);
}
html[data-design-theme="organic"] .hui.radio-option.state-down[data-checked] .radio-dot {
  border-color: var(--semantic-state-down-accent);
}
html[data-design-theme="organic"] .hui.radio-option.state-down[data-checked] .radio-dot-inner {
  background: var(--semantic-state-down-accent);
}

/* HUI: Controls — off state (semantic tints the unchecked appearance) */
html[data-design-theme="organic"] .hui.checkbox-wrap.state-down:not([data-checked]) .checkbox-visual {
  border-color: color-mix(in srgb, var(--semantic-state-down-accent) 40%, var(--hui-control-border));
}
html[data-design-theme="organic"] .hui.switch-wrap.state-down:not([data-checked]) .switch-track {
  background: color-mix(in srgb, var(--semantic-state-down-accent) 25%, var(--hui-switch-track-off-bg));
}
html[data-design-theme="organic"] .hui.radio-option.state-down:not([data-checked]) {
  border-color: color-mix(in srgb, var(--semantic-state-down-accent) 30%, var(--hui-radio-option-border));
}
html[data-design-theme="organic"] .hui.radio-option.state-down:not([data-checked]) .radio-dot {
  border-color: color-mix(in srgb, var(--semantic-state-down-accent) 40%, var(--hui-control-border));
}

/* HUI: Showcase accent */
html[data-design-theme="organic"] .hui.showcase.state-down {
  border-top-color: var(--semantic-state-down-accent);
}
html[data-design-theme="organic"] .hui.showcase.accent-state-down {
  border-top-color: var(--semantic-state-down-accent);
}

/* Forms: fieldset.state-down — tinted container, cascades to children */
html[data-design-theme="organic"] fieldset.state-down {
  background: var(--semantic-state-down-background);
  border-left: var(--card-border-width-accent) var(--card-border-style) var(--semantic-state-down-accent);
  border-radius: var(--radius);
  padding: var(--space-3);
}
fieldset.state-down legend,
html[data-design-theme="organic"] fieldset.state-down [data-slot="legend"] {
  color: var(--semantic-state-down-accent);
  border-bottom-color: var(--semantic-state-down-accent);
}
fieldset.state-down label,
html[data-design-theme="organic"] fieldset.state-down [data-slot="label"] {
  color: var(--semantic-state-down-accent);
}
fieldset.state-down .field-input,
fieldset.state-down .field-select,
fieldset.state-down .field-textarea,
fieldset.state-down [data-slot="input"],
fieldset.state-down [data-slot="select"],
html[data-design-theme="organic"] fieldset.state-down [data-slot="textarea"] {
  border-color: color-mix(in srgb, var(--semantic-state-down-accent) 40%, var(--field-border-color));
}
fieldset.state-down .field-input:focus,
fieldset.state-down .field-select:focus,
fieldset.state-down .field-textarea:focus,
fieldset.state-down [data-slot="input"]:focus,
fieldset.state-down [data-slot="select"]:focus,
html[data-design-theme="organic"] fieldset.state-down [data-slot="textarea"]:focus {
  border-color: var(--semantic-state-down-accent);
  box-shadow: 0 0 0 var(--hui-focus-ring-width) color-mix(in srgb, var(--semantic-state-down-accent) 25%, transparent), var(--field-shadow);
}
fieldset.state-down .field-hint,
html[data-design-theme="organic"] fieldset.state-down [data-slot="description"] {
  color: color-mix(in srgb, var(--semantic-state-down-accent) 60%, var(--text-muted));
}

/* Forms: .field-group.state-down — per-field semantic */
.field-group.state-down label,
html[data-design-theme="organic"] .field-group.state-down [data-slot="label"] {
  color: var(--semantic-state-down-accent);
}
.field-group.state-down .field-input,
.field-group.state-down .field-select,
.field-group.state-down .field-textarea,
.field-group.state-down [data-slot="input"],
.field-group.state-down [data-slot="select"],
html[data-design-theme="organic"] .field-group.state-down [data-slot="textarea"] {
  border-color: color-mix(in srgb, var(--semantic-state-down-accent) 40%, var(--field-border-color));
}
.field-group.state-down .field-input:focus,
.field-group.state-down .field-select:focus,
.field-group.state-down .field-textarea:focus,
.field-group.state-down [data-slot="input"]:focus,
.field-group.state-down [data-slot="select"]:focus,
html[data-design-theme="organic"] .field-group.state-down [data-slot="textarea"]:focus {
  border-color: var(--semantic-state-down-accent);
  box-shadow: 0 0 0 var(--hui-focus-ring-width) color-mix(in srgb, var(--semantic-state-down-accent) 25%, transparent), var(--field-shadow);
}
.field-group.state-down .field-hint,
html[data-design-theme="organic"] .field-group.state-down [data-slot="description"] {
  color: color-mix(in srgb, var(--semantic-state-down-accent) 60%, var(--text-muted));
}

/* ── TYPOGRAPHY ── */
/* ═══════════════════════════════════════
   TYPOGRAPHY CLASSES
   ═══════════════════════════════════════ */
html[data-design-theme="organic"] .typography-display {
  font-family: var(--font-display);
  font-size: var(--font-size-display);
  font-weight: 400;
  line-height: 1.15;
  letter-spacing: -0.02em;
}

html[data-design-theme="organic"] .typography-h1 {
  font-family: var(--font-display);
  font-size: var(--font-size-3xl);
  font-weight: 500;
  line-height: 1.25;
  letter-spacing: -0.015em;
}

html[data-design-theme="organic"] .typography-h2 {
  font-family: var(--font-display);
  font-size: var(--font-size-2xl);
  font-weight: 500;
  line-height: 1.3;
  letter-spacing: -0.01em;
}

html[data-design-theme="organic"] .typography-h3 {
  font-family: var(--font-display);
  font-size: var(--font-size-xl);
  font-weight: 500;
  line-height: 1.35;
  letter-spacing: 0;
}

html[data-design-theme="organic"] .typography-h4 {
  font-family: var(--font-sans);
  font-size: var(--font-size-lg);
  font-weight: 600;
  line-height: 1.4;
}

html[data-design-theme="organic"] .typography-body {
  font-family: var(--font-sans);
