}

html[data-design-theme="organic"] .typography-code {
  font-family: var(--font-mono);
  font-size: var(--font-size-sm);
  font-weight: 400;
  line-height: 1.6;
}

html[data-design-theme="organic"] .typography-caption {
  font-family: var(--font-sans);
