/**
 * intro: Style guide intro hero
 *
 * Hero section with botanical feel -- warm serif typography, linen texture,
 * organic shapes.
 */

html[data-design-theme="organic"] .sg-intro-hero {
  padding: var(--space-10) var(--space-4);
  text-align: center;
  border-bottom: 1px solid var(--border);
  margin-bottom: var(--space-6);
  background: var(--surface);
  background-image: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23D4C9BA' fill-opacity='0.15'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
}
html[data-design-theme="organic"] .sg-intro-title {
  font-family: var(--font-display);
  font-size: 3rem;
  font-weight: 400;
  letter-spacing: -0.02em;
  color: var(--text);
  margin: 0 0 var(--space-2);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
}
html[data-design-theme="organic"] .sg-intro-glyph {
  font-size: 3.5rem;
  margin-bottom: var(--space-2);
}
html[data-design-theme="organic"] .sg-intro-subtitle {
  font-family: var(--font-sans);
  font-size: var(--font-size-xs);
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--blue);
  margin-bottom: var(--space-3);
}
html[data-design-theme="organic"] .sg-intro-quote {
  font-family: var(--font-display);
  font-size: var(--font-size-lg);
  font-style: italic;
  color: var(--text-secondary);
  max-width: 600px;
  margin: 0 auto var(--space-4);
  line-height: 1.5;
}
html[data-design-theme="organic"] .sg-intro-meta {
