  margin-bottom: var(--space-4);
}
html[data-design-theme="organic"] .sg-intro-color-bar span {
  display: block;
  width: 36px;
  height: 36px;
  border-radius: var(--radius);
  box-shadow: 0 2px 6px rgba(44,24,16,0.12);
}
html[data-design-theme="organic"] .sg-intro-meta-cards {
  display: flex;
  justify-content: center;
  gap: var(--space-3);
  flex-wrap: wrap;
}
html[data-design-theme="organic"] .sg-intro-meta-card {
  font-family: var(--font-sans);
  font-size: var(--font-size-xs);
  padding: var(--space-2) var(--space-3);
  background: var(--surface-alt);
  border-radius: var(--radius);
  border: 1px solid var(--border);
}
html[data-design-theme="organic"] .sg-intro-meta-card .label {
  display: block;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-muted);
  margin-bottom: 2px;
}
html[data-design-theme="organic"] .sg-intro-meta-card .value {
  display: block;
  color: var(--text);
  font-weight: 400;
}

/* ── ui-elements ── */
/**
 * ui-elements: Subtle linen background texture
 *
 * A subtle cross-hatch texture that evokes handmade paper or linen fabric.
 * Apply to any surface.
 */

html[data-design-theme="organic"] .linen-texture {
  background-image: url("data:image/svg+xml,%3Csvg width='40' height='40' viewBox='0 0 40 40' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='%23D4C9BA' fill-opacity='0.08'%3E%3Cpath fill-rule='evenodd' d='M0 0h1v1H0V0zm2 2h1v1H2V2zm2-2h1v1H4V0zm2 2h1v1H6V2zm2-2h1v1H8V0zm2 2h1v1h-1V2zm2-2h1v1h-1V0zm2 2h1v1h-1V2zm2-2h1v1h-1V0zm2 2h1v1h-1V2zm2-2h1v1h-1V0zm2 2h1v1h-1V2zm2-2h1v1h-1V0zm2 2h1v1h-1V2zm2-2h1v1h-1V0zm2 2h1v1h-1V2zm2-2h1v1h-1V0zm2 2h1v1h-1V2z'/%3E%3C/g%3E%3C/svg%3E");
}

/**
 * ui-elements: Agent identity badge
 *
 * Inline badge identifying AI agent output. Warm brown accent with organic
 * styling.
 */

html[data-design-theme="organic"] .badge-agent {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 10px;
  font-size: var(--font-size-xs);
  font-family: var(--font-mono);
  font-weight: 500;
  border-radius: var(--radius-sm);
  background: var(--violet-light);
  color: var(--violet);
  border: 1px solid var(--violet-mid);
}

/**
 * ui-elements: Priority level indicator
 *
 * Small colored dot for priority levels P0-P3.
 */

html[data-design-theme="organic"] .priority-dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
}
html[data-design-theme="organic"] .priority-dot--p0 { background: var(--error); }
html[data-design-theme="organic"] .priority-dot--p1 { background: var(--warning); }
html[data-design-theme="organic"] .priority-dot--p2 { background: var(--blue); }
html[data-design-theme="organic"] .priority-dot--p3 { background: var(--gray-400); }

/**
 * ui-elements: Status indicator pill
 *
 * Rounded pill with dot and label for status display.
 */

html[data-design-theme="organic"] .status-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 3px 12px;
  font-size: var(--font-size-xs);
  font-weight: 500;
  border-radius: 999px;
  background: var(--accent-bg, var(--surface-alt));
  color: var(--accent, var(--text-secondary));
}
html[data-design-theme="organic"] .status-pill::before {
  content: "";
  display: inline-block;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--accent, var(--text-muted));
}

/**
 * ui-elements: Dense data table
 *
 * Tighter spacing for dashboard tables with organic warmth.
 */

html[data-design-theme="organic"] .table-compact {
  width: 100%;
  border-collapse: collapse;
  font-size: var(--font-size-sm);
}
html[data-design-theme="organic"] .table-compact th {
  text-align: left;
  font-weight: 600;
  color: var(--text-muted);
  font-size: var(--font-size-xs);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  padding: var(--space-1) var(--space-2);
  border-bottom: 1px solid var(--border);
}
html[data-design-theme="organic"] .table-compact td {
  padding: var(--space-1) var(--space-2);
  border-bottom: 1px solid var(--border);
  color: var(--text);
}

/* ── custom-components ── */
/**
 * custom-components: Unified badge component
 *
 * The foundational status badge -- compact, warm, scannable. Combines with any
 * semantic class for priority, agent status, system state, or feedback.
 */

html[data-design-theme="organic"] .badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 10px;
  font-family: var(--font-mono);
  font-size: var(--font-size-xs);
  font-weight: 500;
  line-height: 1.6;
  border-radius: var(--radius-sm);
  white-space: nowrap;
  vertical-align: middle;
  background: var(--background, var(--surface-alt));
  color: var(--color, var(--text-secondary));
  border: 1px solid color-mix(in srgb, var(--accent, var(--border)) 30%, transparent);
}

/* -- Size variants -- */
html[data-design-theme="organic"] .badge.badge-sm {
  padding: 0 8px;
  font-size: var(--font-size-2xs);
  gap: 3px;
}
html[data-design-theme="organic"] .badge.badge-lg {
  padding: 3px 14px;
  font-size: var(--font-size-sm);
  gap: 6px;
}

/* -- Dot variant: prepend a colored dot -- */
html[data-design-theme="organic"] .badge.badge-dot::before {
  content: "";
  display: inline-block;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  flex-shrink: 0;
  background: var(--accent, var(--text-muted));
}
html[data-design-theme="organic"] .badge.badge-sm.badge-dot::before {
  width: 5px;
  height: 5px;
}

/* -- Pill variant: fully rounded -- */
html[data-design-theme="organic"] .badge.badge-pill {
  border-radius: 999px;
  padding: 2px 12px;
}

/* -- Solid variant: filled background, cream text -- */
html[data-design-theme="organic"] .badge.badge-solid {
  background: var(--accent, var(--gray-400));
  color: #FAF7F2;
  border-color: transparent;
}

/* -- Outline variant: border only, no fill -- */
html[data-design-theme="organic"] .badge.badge-outline {
  background: transparent;
  border-color: var(--accent, var(--border));
}

/* -- Agent badge: monospace with warm brown accent -- */
html[data-design-theme="organic"] .badge.badge-agent {
  font-family: var(--font-mono);
  letter-spacing: 0.02em;
}

/* ── CODE-TERMINAL ── */
/* ═══════════════════════════════════════
   CODE BLOCKS
   ═══════════════════════════════════════ */

/* ─── Inline code ─── */
html[data-design-theme="organic"] .code-inline {
  font-family: var(--font-mono);
  font-size: 0.875em;
  background: var(--code-bg);
  color: var(--code-text);
  border: 1px solid var(--code-border);
  border-radius: var(--radius);
  padding: 0.1em 0.35em;
}

/* ─── Code window shell ─── */
html[data-design-theme="organic"] .code-window {
  border: 1px solid var(--code-border);
  border-radius: var(--radius);
  overflow: hidden;
}

/* ─── Title bar ─── */
html[data-design-theme="organic"] .code-title-bar {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-1) var(--space-2);
  background: var(--code-title-bar-bg, color-mix(in srgb, var(--code-bg) 85%, var(--black)));
  border-bottom: 1px solid var(--code-border);
}

html[data-design-theme="organic"] .code-title-bar-dots {
  display: flex;
  gap: var(--space-half);
}

html[data-design-theme="organic"] .code-title-bar-dots span {
  width: var(--font-size-2xs);
  height: var(--font-size-2xs);
  border-radius: var(--radius-circle);
  background: var(--code-border);
  display: inline-block;
}

html[data-design-theme="organic"] .code-title-bar-filename {
  font-family: var(--font-mono);
  font-size: var(--font-size-xs);
  color: var(--code-comment);
}

/* ─── Code block ─── */
html[data-design-theme="organic"] .code-block {
  margin: 0;
  padding: var(--space-3);
  background: var(--code-bg);
  color: var(--code-text);
  font-family: var(--font-mono);
  font-size: var(--font-size-sm);
  line-height: var(--line-height-relaxed);
  overflow-x: auto;
  tab-size: 2;
}

/* ─── Line-numbered variant ─── */
html[data-design-theme="organic"] .code-block-lined {
  padding: var(--space-2) 0;
}

html[data-design-theme="organic"] .code-line {
  display: flex;
  align-items: baseline;
  gap: var(--space-2);
  padding: 0 var(--space-3);
  min-height: 1.5em;
}

html[data-design-theme="organic"] .code-line:hover {
  background: color-mix(in srgb, var(--code-line-number) 6%, transparent);
}

html[data-design-theme="organic"] .code-line-number {
  flex-shrink: 0;
  min-width: var(--space-3);
  text-align: right;
  color: var(--code-line-number);
  font-size: var(--font-size-xs);
  user-select: none;
}

html[data-design-theme="organic"] .code-line-content {
  flex: 1;
}

/* ═══════════════════════════════════════
   TERMINAL
   ═══════════════════════════════════════ */

/* ─── Terminal window shell ─── */
html[data-design-theme="organic"] .terminal-window {
  border: 1px solid var(--terminal-border);
  border-radius: var(--radius);
  overflow: hidden;
  font-family: var(--font-mono);
}

/* ─── Title bar ─── */
html[data-design-theme="organic"] .terminal-title-bar {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-1) var(--space-2);
  background: var(--terminal-title-bar-bg);
  border-bottom: 1px solid var(--terminal-border);
}

html[data-design-theme="organic"] .terminal-dots {
  display: flex;
  gap: var(--space-half);
  align-items: center;
}

html[data-design-theme="organic"] .terminal-dot {
  width: var(--font-size-2xs);
  height: var(--font-size-2xs);
  border-radius: var(--radius-circle);
  display: inline-block;
}
html[data-design-theme="organic"] .terminal-dot-close { background: var(--screen-dot-close, #ff5f56); }
html[data-design-theme="organic"] .terminal-dot-minimize { background: var(--screen-dot-minimize, #ffbd2e); }
html[data-design-theme="organic"] .terminal-dot-maximize { background: var(--screen-dot-maximize, #27c93f); }

html[data-design-theme="organic"] .terminal-title {
  font-size: var(--font-size-xs);
  color: var(--terminal-output);
  opacity: 0.6;
}

/* ─── Terminal body ─── */
html[data-design-theme="organic"] .terminal-body {
  padding: var(--space-2) var(--space-3);
  background: var(--terminal-bg);
  display: flex;
  flex-direction: column;
  gap: 1px;
}

/* ─── Rows ─── */
html[data-design-theme="organic"] .terminal-row {
  display: flex;
  align-items: baseline;
  gap: var(--space-1);
  padding: var(--space-half) 0;
  line-height: var(--line-height-compact);
}

html[data-design-theme="organic"] .terminal-prompt {
  color: var(--terminal-prompt);
  font-size: var(--font-size-sm);
  user-select: none;
  flex-shrink: 0;
}

html[data-design-theme="organic"] .terminal-command {
  color: var(--terminal-command);
  font-size: var(--font-size-sm);
}

/* ─── Output variants ─── */
html[data-design-theme="organic"] .terminal-output {
  color: var(--terminal-output);
  font-size: var(--font-size-sm);
  padding: 1px 0 1px var(--space-2);
  line-height: var(--line-height-relaxed);
}

html[data-design-theme="organic"] .terminal-success { color: var(--terminal-success); }
html[data-design-theme="organic"] .terminal-error { color: var(--terminal-error); }
html[data-design-theme="organic"] .terminal-warning { color: var(--terminal-warning); }


/* ── GLOBALS ── */
*, *::before, *::after {
  box-sizing: border-box;
}
html {
  font-size: var(--base-font-size);
  line-height: var(--base-line-height);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
}
body {
  font-family: var(--font-sans);
  color: var(--text);
  background: var(--surface);
  margin: 0;
}
a {
  color: var(--text-link);
  text-decoration: none;
}
a:hover {
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 2px;
}
code, pre, kbd, samp {
  font-family: var(--font-mono);
  font-size: var(--font-size-sm);
}
pre {
  background: var(--surface-alt);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: var(--space-2);
  overflow-x: auto;
}
::selection {
  background: var(--blue-mid);
  color: var(--text);
}


