  --theme-violet-mid: color-mix(in srgb, #8B5CF6 30%, var(--surface));
  --theme-rose: color-mix(in srgb, #F43F5E 75%, white);
  --theme-rose-light: color-mix(in srgb, #F43F5E 18%, var(--surface));
  --theme-emerald: color-mix(in srgb, #10B981 75%, white);
  --theme-emerald-light: color-mix(in srgb, #10B981 18%, var(--surface));
  --theme-amber: color-mix(in srgb, #F59E0B 75%, white);
  --theme-amber-light: color-mix(in srgb, #F59E0B 18%, var(--surface));
  --theme-cyan: color-mix(in srgb, #06B6D4 75%, white);
  --theme-cyan-light: color-mix(in srgb, #06B6D4 18%, var(--surface));
  --theme-indigo: color-mix(in srgb, #6366F1 75%, white);
  --theme-indigo-light: color-mix(in srgb, #6366F1 18%, var(--surface));
  --theme-teal: color-mix(in srgb, #14B8A6 75%, white);
  --theme-teal-light: color-mix(in srgb, #14B8A6 18%, var(--surface));
  --theme-orange: color-mix(in srgb, #F97316 75%, white);
  --theme-orange-light: color-mix(in srgb, #F97316 18%, var(--surface));
  --theme-sky: color-mix(in srgb, #0EA5E9 75%, white);
  --theme-sky-light: color-mix(in srgb, #0EA5E9 18%, var(--surface));
  --theme-lime: color-mix(in srgb, #84CC16 75%, white);
  --theme-lime-light: color-mix(in srgb, #84CC16 18%, var(--surface));
  --theme-pink: color-mix(in srgb, #EC4899 75%, white);
  --theme-pink-light: color-mix(in srgb, #EC4899 18%, var(--surface));
  --theme-purple: color-mix(in srgb, #A855F7 75%, white);
  --theme-purple-light: color-mix(in srgb, #A855F7 18%, var(--surface));
  --theme-fuchsia: color-mix(in srgb, #D946EF 75%, white);
  --theme-fuchsia-light: color-mix(in srgb, #D946EF 18%, var(--surface));
  --theme-success: color-mix(in srgb, #10B981 75%, white);
  --theme-success-tint: color-mix(in srgb, #10B981 18%, var(--surface));
  --theme-warning: color-mix(in srgb, #F59E0B 75%, white);
  --theme-warning-tint: color-mix(in srgb, #F59E0B 18%, var(--surface));
  --theme-error: color-mix(in srgb, #EF4444 75%, white);
  --theme-error-tint: color-mix(in srgb, #EF4444 18%, var(--surface));
  --theme-info: color-mix(in srgb, #3B82F6 75%, white);
  --theme-info-tint: color-mix(in srgb, #3B82F6 18%, var(--surface));
  --theme-card-background: var(--gray-800);
  --theme-card-border-color: var(--gray-700);
  --theme-btn-background: #2563EB;
  --theme-btn-hover-background: #3B82F6;
}

/* Alias layer: bare names → themed vars */
html[data-design-theme="style-guide"] {
  --surface: var(--theme-surface);
  --surface-alt: var(--theme-surface-alt);
  --surface-inverse: var(--theme-surface-inverse);
  --text: var(--theme-text);
  --text-secondary: var(--theme-text-secondary);
  --text-muted: var(--theme-text-muted);
  --text-inverse: var(--theme-text-inverse);
  --text-link: var(--theme-text-link);
  --border: var(--theme-border);
  --border-strong: var(--theme-border-strong);
  --shadow-color: var(--theme-shadow-color);
}

/* Alias layer: bare names → themed vars */
html[data-design-theme="style-guide"].dark {
  --blue: var(--theme-blue);
  --blue-light: var(--theme-blue-light);
  --blue-mid: var(--theme-blue-mid);
  --violet: var(--theme-violet);
  --violet-light: var(--theme-violet-light);
  --violet-mid: var(--theme-violet-mid);
  --rose: var(--theme-rose);
  --rose-light: var(--theme-rose-light);
  --emerald: var(--theme-emerald);
  --emerald-light: var(--theme-emerald-light);
  --amber: var(--theme-amber);
  --amber-light: var(--theme-amber-light);
  --cyan: var(--theme-cyan);
  --cyan-light: var(--theme-cyan-light);
  --indigo: var(--theme-indigo);
  --indigo-light: var(--theme-indigo-light);
  --teal: var(--theme-teal);
  --teal-light: var(--theme-teal-light);
  --orange: var(--theme-orange);
  --orange-light: var(--theme-orange-light);
  --sky: var(--theme-sky);
  --sky-light: var(--theme-sky-light);
  --lime: var(--theme-lime);
  --lime-light: var(--theme-lime-light);
  --pink: var(--theme-pink);
  --pink-light: var(--theme-pink-light);
  --purple: var(--theme-purple);
  --purple-light: var(--theme-purple-light);
  --fuchsia: var(--theme-fuchsia);
  --fuchsia-light: var(--theme-fuchsia-light);
  --success: var(--theme-success);
  --success-tint: var(--theme-success-tint);
  --warning: var(--theme-warning);
  --warning-tint: var(--theme-warning-tint);
  --error: var(--theme-error);
  --error-tint: var(--theme-error-tint);
  --info: var(--theme-info);
  --info-tint: var(--theme-info-tint);
  --card-background: var(--theme-card-background);
  --card-border-color: var(--theme-card-border-color);
  --btn-background: var(--theme-btn-background);
  --btn-hover-background: var(--theme-btn-hover-background);
}

.content {
  max-width: var(--layout-dashboard-max-width); padding: var(--layout-dashboard-padding); margin: var(--layout-dashboard-margin); background: var(--layout-dashboard-content-bg)
}

.content.standard {
  max-width: var(--layout-standard-max-width); padding: var(--layout-standard-padding); margin: var(--layout-standard-margin); background: var(--layout-standard-content-bg)
}

.content.article {
  max-width: var(--layout-article-max-width); padding: var(--layout-article-padding); margin: var(--layout-article-margin); background: var(--layout-article-content-bg)
}

.content.focus {
  max-width: var(--layout-focus-max-width); padding: var(--layout-focus-padding); margin: var(--layout-focus-margin); background: var(--layout-focus-content-bg)
}

/* ── BRANDING ── */
/* ═══════════════════════════════════════
   PRODUCT BRANDING
   Layout handled by Tailwind classes on the component.
   ═══════════════════════════════════════ */
html[data-design-theme="style-guide"] .product-branding {
  border: var(--branding-border);
  margin-bottom: var(--space-8);
}
html[data-design-theme="style-guide"] .product-branding-logo {
  background: var(--branding-logo-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: var(--space-6);
  min-height: var(--space-25);
}
html[data-design-theme="style-guide"] .product-branding-logo svg {
  max-width: var(--branding-logo-max-width);
  max-height: var(--branding-logo-max-height);
}
html[data-design-theme="style-guide"] .product-branding-logo-placeholder {
  width: var(--branding-placeholder-width);
  height: var(--branding-placeholder-height);
  border: var(--branding-placeholder-border);
