  letter-spacing: var(--branding-name-letter-spacing);
  margin-bottom: var(--space-3);
  padding-bottom: var(--space-2);
  border-bottom: var(--branding-name-border);
}
html[data-design-theme="style-guide"] .product-branding-field-label {
  font-family: var(--micro-label-font-family);
  font-size: var(--micro-label-font-size);
  font-weight: var(--micro-label-font-weight);
  text-transform: var(--micro-label-text-transform);
  letter-spacing: var(--micro-label-letter-spacing);
  color: var(--micro-label-color);
  margin-bottom: var(--size-dot);
}
html[data-design-theme="style-guide"] .product-branding-field-value {
  font-size: var(--branding-field-value-font-size);
  line-height: var(--branding-field-value-line-height);
  color: var(--branding-field-value-color);
}
html[data-design-theme="style-guide"] .product-branding-tags {
  display: flex;
  flex-wrap: wrap;
  gap: var(--branding-keyword-gap);
  margin-top: var(--branding-keyword-margin-top);
}
html[data-design-theme="style-guide"] .product-branding-tag {
  font-family: var(--micro-label-font-family);
  font-size: var(--micro-label-font-size);
  font-weight: var(--font-weight-medium);
  padding: var(--branding-keyword-padding);
  border: var(--branding-keyword-border);
  color: var(--branding-keyword-color);
}

/* ── SECTIONS ── */
/* ═══════════════════════════════════════
   SECTION HEADERS
   ═══════════════════════════════════════ */
html[data-design-theme="style-guide"] .sg-section-header {
  border-bottom: var(--sg-border);
  margin-bottom: var(--space-3);
  padding-bottom: var(--space-2);
  display: flex;
  align-items: flex-start;
  gap: var(--space-2);
  margin-top: var(--space-6);
}
html[data-design-theme="style-guide"] .sg-section-number {
  font-family: var(--micro-label-font-family);
  font-size: var(--micro-label-font-size);
  font-weight: var(--micro-label-font-weight);
  color: var(--sg-section-number-color);
  background: var(--sg-section-number-bg);
  border: var(--sg-section-number-border);
  border-radius: var(--sg-section-number-radius);
  padding: var(--sg-section-number-padding);
  letter-spacing: var(--sg-section-number-letter-spacing);
  white-space: nowrap;
}
html[data-design-theme="style-guide"] .sg-section-title-group {
  flex: 1;
}
html[data-design-theme="style-guide"] .sg-section-title {
  font-family: var(--sg-section-title-font-family);
  font-size: var(--sg-section-title-font-size);
  font-weight: var(--font-weight-bold);
  letter-spacing: var(--sg-section-title-letter-spacing);
  text-transform: var(--sg-section-title-text-transform);
  color: var(--sg-section-title-color);
  margin-bottom: var(--space-quarter);
  display: flex;
  align-items: baseline;
  gap: var(--space-1);
}
html[data-design-theme="style-guide"] .sg-section-desc {
  font-size: var(--font-size-sm);
  color: var(--sg-section-desc-color);
  font-family: var(--sg-section-desc-font-family);
  line-height: var(--line-height-normal);
}

/* ─── Type Specimen Card ─── */
html[data-design-theme="style-guide"] .sg-type-specimen {
  background: var(--sg-type-specimen-bg);
  border: var(--sg-type-specimen-border);
  border-bottom: var(--sg-type-specimen-border-bottom);
  border-radius: var(--sg-type-specimen-radius);
  padding: var(--sg-type-specimen-padding);
  margin: var(--sg-type-specimen-margin);
}
html[data-design-theme="style-guide"] .sg-type-specimen .font-mono.font-bold {
  color: var(--sg-type-specimen-name-color);
  font-family: var(--sg-type-specimen-name-font);
}

/* ─── Subsection Title ─── */
.sg-subsection-title,
html[data-design-theme="style-guide"] .sg-subsection {
  font-family: var(--micro-label-font-family);
  font-size: var(--micro-label-font-size);
  font-weight: var(--micro-label-font-weight);
  text-transform: var(--micro-label-text-transform);
  letter-spacing: var(--micro-label-letter-spacing);
  color: var(--text-muted);
  margin-bottom: var(--space-2);
  margin-top: var(--space-4);
  padding-bottom: var(--space-1);
  border-bottom: var(--sg-border);
}

/* ─── Section Groups ─── */
html[data-design-theme="style-guide"] .sg-group {
  margin-top: var(--space-8);
  padding-top: var(--space-8);
  border-top: var(--sg-border);
}
html[data-design-theme="style-guide"] .sg-group:first-child,
html[data-design-theme="style-guide"] .sg-group:first-of-type {
  border-top: none;
  padding-top: 0;
}
html[data-design-theme="style-guide"] .sg-group-header {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  cursor: pointer;
  user-select: none;
  padding-bottom: var(--space-2);
  margin-bottom: 0;
}
html[data-design-theme="style-guide"] .sg-group-label {
  font-family: var(--micro-label-font-family);
  font-size: var(--micro-label-font-size);
  font-weight: var(--micro-label-font-weight);
  text-transform: var(--micro-label-text-transform);
  letter-spacing: var(--letter-spacing-widest);
  color: var(--text-muted);
  white-space: nowrap;
}
html[data-design-theme="style-guide"] .sg-group-line {
  flex: 1;
  height: var(--border-thick);
  background: var(--text-muted);
}
html[data-design-theme="style-guide"] .sg-group-toggle {
  font-size: var(--font-size-xs);
  color: var(--text-muted);
  transition: transform var(--transition-medium) ease;
  display: inline-flex;
  align-items: center;
}
html[data-design-theme="style-guide"] .sg-group-contents {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--sg-group-content-gap);
}
html[data-design-theme="style-guide"] .sg-group-content-item {
  font-family: var(--micro-label-font-family);
  font-size: var(--micro-label-font-size);
  color: var(--text-muted);
  padding: var(--sg-group-content-padding);
  border: var(--sg-border);
  white-space: nowrap;
  letter-spacing: 0.03em;
  transition: color var(--transition-fast), border-color var(--transition-fast);
}
html[data-design-theme="style-guide"] .sg-group-header:hover .sg-group-content-item {
  color: var(--text-secondary);
  border-color: var(--border-strong);
}
html[data-design-theme="style-guide"] .sg-group-content-item .sg-group-item-num {
  color: var(--border);
  margin-right: var(--sg-group-item-margin-right);
}

/* ─── Showcase Utilities ─── */

/* Section head label — used above subsections (e.g. "UI Glyphs", "Typography") */
html[data-design-theme="style-guide"] .sg-section-head {
  font-family: var(--micro-label-font-family);
  font-size: var(--font-size-sm);
  font-weight: var(--micro-label-font-weight);
  letter-spacing: var(--letter-spacing-label);
  text-transform: var(--micro-label-text-transform);
  color: var(--text-muted);
  margin-bottom: var(--space-2);
}

/* Principle row — 3-col flex: label | text */
html[data-design-theme="style-guide"] .sg-principle-row {
  display: flex;
  gap: var(--space-3);
  align-items: baseline;
}
html[data-design-theme="style-guide"] .sg-principle-label {
  font-size: var(--font-size-sm);
  font-family: var(--micro-label-font-family);
  font-weight: var(--micro-label-font-weight);
  letter-spacing: var(--sg-section-number-letter-spacing);
  text-transform: var(--micro-label-text-transform);
  white-space: nowrap;
  min-width: var(--sg-principle-label-width);
  padding-top: var(--sg-hairline);
  flex-shrink: 0;
}
html[data-design-theme="style-guide"] .sg-principle-text {
  font-size: var(--font-size-sm);
  line-height: var(--line-height-relaxed);
  color: var(--text);
  margin: 0;
}
html[data-design-theme="style-guide"] .sg-principle-text.muted {
  color: var(--text-secondary);
  font-style: italic;
}

/* ─── Principle Label Colors ─── */
html[data-design-theme="style-guide"] .text-principle { color: var(--brand-red); }
html[data-design-theme="style-guide"] .text-approach { color: var(--text-muted); }
html[data-design-theme="style-guide"] .text-why { color: var(--brand-blue); }
html[data-design-theme="style-guide"] .dark .text-principle { color: color-mix(in srgb, var(--brand-red) 75%, white); }
html[data-design-theme="style-guide"] .dark .text-why { color: color-mix(in srgb, var(--brand-blue) 75%, white); }

/* Demo container — gray-50 box with border */
html[data-design-theme="style-guide"] .sg-demo-box {
  padding: var(--space-3);
  background: var(--surface-alt);
  border: var(--sg-border);
}

/* ─── Anchor Headings ─── */
html[data-design-theme="style-guide"] .sg-anchor-heading {
  cursor: pointer;
  display: flex;
  align-items: baseline;
  gap: var(--space-1);
}
html[data-design-theme="style-guide"] .sg-anchor-heading-icon {
  font-size: var(--font-size-lg);
  user-select: none;
}

/* Section description text */
html[data-design-theme="style-guide"] .sg-description {
  font-size: var(--font-size-sm);
  color: var(--text-muted);
  margin-bottom: var(--space-2);
  max-width: var(--sg-description-max-width);
  line-height: var(--line-height-relaxed);
}

/* ─── Preview / Code Toggle ─── */
html[data-design-theme="style-guide"] .sg-preview-code {
  border: var(--sg-border);
  margin-bottom: var(--space-3);
}
html[data-design-theme="style-guide"] .sg-preview-code-tabs {
  display: flex;
  align-items: center;
  gap: 0;
  border-bottom: var(--sg-border);
  background: var(--surface-alt);
}
html[data-design-theme="style-guide"] .sg-preview-code-tab {
  font-family: var(--micro-label-font-family);
  font-size: var(--micro-label-font-size);
  font-weight: var(--font-weight-semibold);
  text-transform: var(--micro-label-text-transform);
  letter-spacing: var(--letter-spacing-label);
  padding: var(--space-1) var(--space-2);
  background: none;
  border: none;
  border-bottom: var(--border-thick) solid transparent;
  color: var(--text-muted);
  cursor: pointer;
  transition: color var(--transition-base) ease, border-color var(--transition-base) ease;
}
html[data-design-theme="style-guide"] .sg-preview-code-tab:hover {
  color: var(--text-secondary);
}
html[data-design-theme="style-guide"] .sg-preview-code-tab.active {
  color: var(--text);
  border-bottom-color: var(--text);
}
html[data-design-theme="style-guide"] .sg-preview-code-copy {
  margin-left: auto;
  font-family: var(--micro-label-font-family);
  font-size: var(--micro-label-font-size);
  font-weight: var(--font-weight-semibold);
  padding: var(--space-half) var(--space-1);
  margin-right: var(--space-1);
  background: var(--surface);
  border: var(--sg-border);
  color: var(--text-muted);
  cursor: pointer;
}
html[data-design-theme="style-guide"] .sg-preview-code-copy:hover {
  color: var(--text);
  border-color: var(--border-strong);
}
html[data-design-theme="style-guide"] .sg-preview-code-preview {
  padding: var(--space-3);
  background: var(--surface);
}

/* ─── Screen Frame Mockups ─── */
html[data-design-theme="style-guide"] .screen-frame {
  background: var(--surface);
  border: var(--border-thick) solid var(--text);
  overflow: hidden;
  margin-bottom: var(--space-4);
  box-shadow: var(--sg-screen-shadow);
}
html[data-design-theme="style-guide"] .screen-titlebar {
  background: var(--surface-inverse);
  padding: var(--size-2xs) var(--size-space-2);
  display: flex;
  align-items: center;
  gap: var(--space-1);
}
html[data-design-theme="style-guide"] .screen-dot {
  width: var(--size-2xs);
  height: var(--size-2xs);
  border-radius: var(--radius-circle);
  background: var(--border-strong);
}
html[data-design-theme="style-guide"] .screen-dot:first-child { background: var(--brand-red); }
html[data-design-theme="style-guide"] .screen-dot:nth-child(2) { background: var(--brand-yellow); }
html[data-design-theme="style-guide"] .screen-dot:nth-child(3) { background: var(--success); }
html[data-design-theme="style-guide"] .screen-url {
  font-family: var(--micro-label-font-family);
  font-size: var(--micro-label-font-size);
  color: var(--text-muted);
  margin-left: var(--space-1);
  background: var(--surface-alt);
  padding: var(--border-heavy) var(--space-1-mid);
  flex: 1;
  max-width: var(--sg-screen-url-max-width);
}
html[data-design-theme="style-guide"] .screen-body {
  padding: 0;
  aspect-ratio: 16 / 9;
  display: flex;
  align-items: stretch;
  background: var(--surface);
  color: var(--text);
}
html[data-design-theme="style-guide"] .screen-body > * {
  width: 100%;
  height: 100%;
}
html[data-design-theme="style-guide"] .screen-label {
  font-family: var(--micro-label-font-family);
  font-size: var(--font-size-2xs);
  font-weight: var(--font-weight-semibold);
  text-transform: var(--micro-label-text-transform);
  letter-spacing: var(--letter-spacing-wider);
  color: var(--text-muted);
  margin-bottom: var(--space-1);
}

/* ─── Color Mode Toggle ─── */
html[data-design-theme="style-guide"] .sg-mode-toggle {
