}
html[data-design-theme="style-guide"] body[data-shell] .shell-grid {
  display: grid;
  height: 100vh;
  grid-template-areas:
    "nav    nav    nav"
    "side   main   aside"
    "foot   foot   foot";
  grid-template-rows: var(--shell-navbar-height, 0px) 1fr var(--shell-footer-height, 0px);
  grid-template-columns: var(--shell-sidebar-width, 0px) 1fr var(--shell-aside-width, 0px);
}

/* ─── Navbar ─── */
html[data-design-theme="style-guide"] body[data-shell] .shell-grid > .shell-navbar {
  display: flex;
  grid-area: nav;
  z-index: var(--shell-navbar-z-index);
