}
html[data-design-theme="style-guide"] .shell-aside-label { opacity: var(--shell-aside-meta-opacity); font-size: var(--shell-aside-meta-font-size); }
html[data-design-theme="style-guide"] .shell-aside-value { font-family: var(--font-mono); font-size: var(--shell-aside-meta-font-size); }

/* ─── Footer ─── */
html[data-design-theme="style-guide"] body[data-shell] .shell-grid > .shell-footer {
  display: flex;
  grid-area: foot;
  z-index: var(--shell-footer-z-index);
  height: var(--shell-footer-height);
  background: var(--shell-footer-bg, var(--surface-alt));
  color: var(--shell-footer-color, var(--text-muted));
  align-items: center;
  padding: 0 var(--space-3);
  font-size: var(--shell-footer-font-size);
  font-family: var(--font-mono);
  gap: var(--space-3);
  border-top: var(--shell-footer-border-width) solid var(--border);
}
html[data-design-theme="style-guide"] .shell-footer-dot {
  width: var(--shell-footer-dot-size); height: var(--shell-footer-dot-size); border-radius: 50%; flex-shrink: 0;
}
html[data-design-theme="style-guide"] .shell-footer-sep { opacity: var(--shell-footer-dot-opacity); }

/* ─── Main content area ─── */
html[data-design-theme="style-guide"] body[data-shell] .shell-grid > .content {
  grid-area: main;
  padding-top: var(--space-4);
  min-width: 0;
  overflow-y: auto;
  container-type: normal;
}

/* ─── Per-shell vars ─── */
/* Shell: app-shell */
html[data-design-theme="style-guide"] body[data-shell="app-shell"] {
  --shell-navbar-height: 48px;
  --shell-navbar-bg: var(--gray-900);
  --shell-navbar-color: var(--gray-100);
  --shell-sidebar-width: 240px;
  --shell-sidebar-bg: var(--gray-800);
  --shell-sidebar-color: var(--gray-200);
  --shell-footer-height: 28px;
  --shell-footer-bg: var(--gray-100);
  --shell-footer-color: var(--gray-500);
  --shell-aside-width: 0px;
}
html[data-design-theme="style-guide"] body[data-shell="app-shell"] .shell-grid > .shell-aside { display: none; }

/* Shell: focus-shell */
html[data-design-theme="style-guide"] body[data-shell="focus-shell"] {
  --shell-navbar-height: 48px;
  --shell-navbar-bg: var(--surface-alt);
  --shell-navbar-color: var(--text);
  --shell-sidebar-width: 0px;
  --shell-aside-width: 0px;
  --shell-footer-height: 0px;
}
