html[data-design-theme="style-guide"] body[data-shell="focus-shell"] .shell-grid > .shell-aside { display: none; }
html[data-design-theme="style-guide"] body[data-shell="focus-shell"] .shell-grid > .shell-footer { display: none; }

/* Shell: editor */
html[data-design-theme="style-guide"] body[data-shell="editor"] {
  --shell-navbar-height: 40px;
  --shell-navbar-bg: var(--gray-900);
  --shell-navbar-color: var(--gray-100);
  --shell-sidebar-width: 220px;
  --shell-sidebar-bg: var(--gray-800);
  --shell-sidebar-color: var(--gray-300);
  --shell-aside-width: 260px;
  --shell-aside-bg: var(--gray-800);
  --shell-aside-color: var(--gray-300);
  --shell-footer-height: 0px;
}
html[data-design-theme="style-guide"] body[data-shell="editor"] .shell-grid > .shell-footer { display: none; }

/* Shell: document */
html[data-design-theme="style-guide"] body[data-shell="document"] {
  --shell-navbar-height: 48px;
  --shell-navbar-bg: var(--surface-alt);
  --shell-navbar-color: var(--text);
  --shell-sidebar-width: 200px;
  --shell-sidebar-bg: var(--surface-alt);
  --shell-sidebar-color: var(--text-secondary);
  --shell-aside-width: 0px;
  --shell-footer-height: 0px;
}
html[data-design-theme="style-guide"] body[data-shell="document"] .shell-grid > .shell-aside { display: none; }
html[data-design-theme="style-guide"] body[data-shell="document"] .shell-grid > .shell-footer { display: none; }

/* ═══════════════════════════════════════
   SCREEN FRAME
   ═══════════════════════════════════════ */
html[data-design-theme="style-guide"] .screen-frame {
  border-radius: var(--screen-frame-radius);
  overflow: hidden;
  box-shadow: var(--screen-frame-shadow);
  border: var(--screen-frame-border-width) solid var(--border-strong);
  background: var(--surface);
}
html[data-design-theme="style-guide"] .screen-titlebar {
  display: flex;
  align-items: center;
  gap: var(--screen-titlebar-gap);
  padding: var(--screen-titlebar-padding);
  background: var(--surface-alt);
  border-bottom: var(--border-thin) solid var(--border);
}
html[data-design-theme="style-guide"] .screen-dots {
  display: flex;
  gap: var(--screen-dots-gap);
  flex-shrink: 0;
}
html[data-design-theme="style-guide"] .screen-dot {
  width: var(--screen-dot-size);
  height: var(--screen-dot-size);
  border-radius: 50%;
}
html[data-design-theme="style-guide"] .screen-dot:nth-child(1) { background: var(--screen-dot-close); }
html[data-design-theme="style-guide"] .screen-dot:nth-child(2) { background: var(--screen-dot-minimize); }
html[data-design-theme="style-guide"] .screen-dot:nth-child(3) { background: var(--screen-dot-maximize); }
html[data-design-theme="style-guide"] .screen-url {
  flex: 1;
