html[data-design-theme="style-guide"] .hui.listbox-option[data-active] {
  background: var(--hui-panel-item-active-bg);
  color: var(--hui-panel-item-active-color);
}
html[data-design-theme="style-guide"] .hui.listbox-option[data-selected] { font-weight: var(--hui-panel-item-selected-weight); }

/* ─── Combobox ─── */
html[data-design-theme="style-guide"] .hui.combo-wrap { position: relative; }
html[data-design-theme="style-guide"] .hui.combo-input {
  display: block;
